import{U as e,W as t,nt as n,t as r}from"./chunks/framework.CPHJXLir.js";var i=JSON.parse(`{"title":"科技空岛新手入门","description":"刚到 PotgCraft 科技空岛？从创建岛屿、返回基地和打开任务菜单开始，认识漂流钓鱼与资源额度。","frontmatter":{"title":"科技空岛新手入门","description":"刚到 PotgCraft 科技空岛？从创建岛屿、返回基地和打开任务菜单开始，认识漂流钓鱼与资源额度。"},"headers":[],"relativePath":"skyblock/getting-started.md","filePath":"skyblock/getting-started.md"}`),a={name:`skyblock/getting-started.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="第一次上岛-先把家安下来" tabindex="-1">第一次上岛，先把家安下来 <a class="header-anchor" href="#第一次上岛-先把家安下来" aria-label="Permalink to “第一次上岛，先把家安下来”">​</a></h1><p>别急着把整座岛铺满机器，先想想第一批资源从哪里来。这份指南帮你找到岛屿面板、任务和资源入口，方便开始自己的建设计划。</p><div class="info custom-block"><p class="custom-block-title">还没有进入科技空岛？</p><p>这里需要匹配的 Java 1.21.1 模组客户端。整合包下载与连接方式仍待补充，先看 <a href="./#join">加入说明</a>，不要拿增强生存的客户端下载入口代替。</p></div><h2 id="_1-创建或管理自己的岛屿" tabindex="-1">1. 创建或管理自己的岛屿 <a class="header-anchor" href="#_1-创建或管理自己的岛屿" aria-label="Permalink to “1. 创建或管理自己的岛屿”">​</a></h2><p>在聊天栏输入：</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/is</span></span></code></pre></div><p>根据当前菜单创建或管理岛屿；如果准备和朋友同住，可以先商量由谁建岛，再按服内界面加入。可用模板与权限以实际菜单为准。</p><p>想回到自己的岛屿：</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/is tp</span></span></code></pre></div><h2 id="_2-打开岛屿管理面板" tabindex="-1">2. 打开岛屿管理面板 <a class="header-anchor" href="#_2-打开岛屿管理面板" aria-label="Permalink to “2. 打开岛屿管理面板”">​</a></h2><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/is panel</span></span></code></pre></div><p>先熟悉返回岛屿、成员、权限、任务和升级等入口。多人合作时，先确认每个人的权限和分工，再开始集中存放资源或改动设备。</p><h2 id="_3-在任务里找一个起步目标" tabindex="-1">3. 在任务里找一个起步目标 <a class="header-anchor" href="#_3-在任务里找一个起步目标" aria-label="Permalink to “3. 在任务里找一个起步目标”">​</a></h2><p>从管理面板进入任务，也可以输入：</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/is missions</span></span></code></pre></div><p>看看当前能完成的矿工、农夫、渔夫等任务，先读目标，再读奖励。部分奖励与生成器成长、漂流鱼竿升级芯片有关，具体要求以游戏内任务为准。</p><p>不必把任务当作必须照走的科技顺序，也不要默认所有机器产出都会计入任务统计。更多说明见 <a href="./resources.html">岛屿成长与资源生产</a>。</p><h2 id="_4-认识漂流鱼竿-找基础材料与种源" tabindex="-1">4. 认识漂流鱼竿，找基础材料与种源 <a class="header-anchor" href="#_4-认识漂流鱼竿-找基础材料与种源" aria-label="Permalink to “4. 认识漂流鱼竿，找基础材料与种源”">​</a></h2><p>使用<strong>专用漂流鱼竿</strong>在空旷位置向空气抛竿，等待咬钩后收竿，可以从该等级奖池获得材料。普通鱼竿或只改了名字的鱼竿不能替代它。</p><p><strong>初始漂流鱼竿的具体获取方式仍待服主确认。</strong> 请先查看当前服内引导或向管理员询问，不要尝试网上的管理员发放命令。</p><ul><li><a href="./fishing.html">漂流钓鱼指南</a>：抛竿方式、等级区别与常见问题。</li><li><a href="./fishing-rewards.html">六级完整奖池</a>：缺什么材料，先查哪一根竿能钓到。</li><li><a href="./../guides/xplus-autofish.html">XPlus 参考设置</a>：已经在使用对应辅助功能时，可按教程尝试。</li></ul><h2 id="_5-看看生成器-以及全岛共用的额度" tabindex="-1">5. 看看生成器，以及全岛共用的额度 <a class="header-anchor" href="#_5-看看生成器-以及全岛共用的额度" aria-label="Permalink to “5. 看看生成器，以及全岛共用的额度”">​</a></h2><p>通过面板查看岛屿升级，或输入：</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/is upgrade</span></span></code></pre></div><p>矿物生成器的产出随等级变化，同时受岛屿共享的矿物生成额度影响。查看当前位置所属范围的额度：</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/bq status</span></span></code></pre></div><p>额度按时间恢复，限制的是新生成的矿物方块，不是已经收进仓库的库存。不要因为暂时产出普通石头，就急着拆掉整套设备，先检查 <a href="./resources.html#quota">资源额度说明</a>。</p><h2 id="_6-再决定你的第一条产线" tabindex="-1">6. 再决定你的第一条产线 <a class="header-anchor" href="#_6-再决定你的第一条产线" aria-label="Permalink to “6. 再决定你的第一条产线”">​</a></h2><p>有了起步材料，再挑一件想省力的事：整理箱子、运输物品、加工材料，或者建设农场。科技模组可以按需要组合，玩法介绍里整理了 <a href="./#让零散机器连成生产线">机器、能源与仓储的用途</a>。</p><p>暂时卡住也没关系。带上任务条件、鱼竿等级或设备情况去群里聊聊，比只说“为什么不工作”更容易一起找到原因。</p><p>接着阅读：<a href="./commands.html">常用命令速查</a> · <a href="./resources.html">任务与资源生产</a> · <a href="./../guides/">玩法知识库</a></p>`,31)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};